WITH src AS (SELECT *, CASE WHEN rating >= 3.6 THEN 'High' WHEN rating >= 1.7 THEN 'Medium' ELSE 'Low' END AS rating_band FROM suppliers WHERE country IN ('US', 'JP') AND (rating BETWEEN 2.2 AND 3.5 OR supplier_name LIKE '%Toky%')), agg AS (SELECT city, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore FROM src GROUP BY city) SELECT city, pct_singapore FROM agg WHERE pct_singapore < 63;
